import { chromium } from 'playwright';
import fs from 'node:fs';
const OUT='/tmp/chapter5-pass3';fs.mkdirSync(OUT,{recursive:true});
function assert(c,m){if(!c)throw new Error(m)}
const browser=await chromium.launch({headless:true});
const ctx=await browser.newContext({viewport:{width:390,height:844},deviceScaleFactor:1,reducedMotion:'no-preference'});
const stars={};for(let i=1;i<=250;i++)stars[i]=3;
await ctx.addInitScript(({stars})=>{localStorage.setItem('latchlings_campaign400_progress_v1',JSON.stringify({unlocked:251,stars}));localStorage.setItem('latchlings_cinematics_seen_v1',JSON.stringify({opening:1,'across-drift':1,'old-maps':1,homeward:1}));},{stars});
const page=await ctx.newPage();page.setDefaultTimeout(12000);const errors=[];page.on('pageerror',e=>errors.push(String(e)));await page.goto('http://127.0.0.1:4173/',{waitUntil:'networkidle'});
await page.evaluate(()=>eval("chapterView=5;rangeView=2;screen('levels');renderChapter()"));await page.waitForTimeout(760);await page.evaluate(()=>{const s=document.getElementById('storyCardOverlay');if(s){s.classList.remove('show');s.setAttribute('aria-hidden','true')}});
const atlas=await page.evaluate(()=>{const map=document.getElementById('levelGrid'),e=map.querySelector('.atlas-scene em'),r=e.getBoundingClientRect(),nodes=[...map.querySelectorAll('.atlas-node')].map(n=>{const x=n.getBoundingClientRect();return {level:n.dataset.level,left:x.left,top:x.top,right:x.right,bottom:x.bottom}}),overlaps=nodes.filter(n=>!(r.right<=n.left||r.left>=n.right||r.bottom<=n.top||r.top>=n.bottom)).map(n=>n.level),b=getComputedStyle(e,'::before'),a=getComputedStyle(e,'::after');return {landmark:{left:r.left,top:r.top,right:r.right,bottom:r.bottom},overlaps,scopeBg:b.backgroundImage,scopeTransform:b.transform,lights:a.boxShadow}});
assert(atlas.overlaps.length===0,'Prism lookout overlaps Atlas level nodes: '+JSON.stringify(atlas));assert(atlas.scopeBg!=='none'&&atlas.scopeTransform!=='none'&&atlas.lights!=='none','Prism lookout details missing: '+JSON.stringify(atlas));await page.screenshot({path:`${OUT}/chapter5-atlas-lookout-final-390.png`,fullPage:false});
await page.evaluate(()=>window.focusHomeReward('telescope'));await page.waitForTimeout(760);const frame=page.frameLocator('#homeTitleFrame');await frame.locator('#c2 .story-telescope').waitFor({state:'visible'});const home=await frame.locator('#c2 .phone').evaluate(phone=>{const t=phone.querySelector('.story-telescope'),r=t.getBoundingClientRect(),pr=phone.getBoundingClientRect(),s=getComputedStyle(t);return {focus:phone.classList.contains('story-focus-telescope'),display:s.display,filter:s.filter,boxShadow:s.boxShadow,inside:r.left>=pr.left&&r.right<=pr.right&&r.top>=pr.top&&r.bottom<=pr.bottom,rect:{left:r.left,top:r.top,right:r.right,bottom:r.bottom}}});assert(home.focus&&home.display!=='none'&&home.filter!=='none'&&home.boxShadow!=='none'&&home.inside,'Telescope focus lacks visible contained emphasis: '+JSON.stringify(home));await page.screenshot({path:`${OUT}/chapter5-home-telescope-focus-final-390.png`,fullPage:false});
assert(errors.length===0,'Browser errors: '+JSON.stringify(errors));fs.writeFileSync(`${OUT}/visual-refinement.json`,JSON.stringify({atlas,home},null,2));console.log('CHAPTER5_VISUAL_REFINEMENTS_ACCEPTED',JSON.stringify({atlas,home}));await browser.close();
